mod tests {
    use super::*;

    #[test]
    fn test_plugin_path() {
        assert_eq!(plugin_path("incus"), "/org/opdbus/v1/plugins/incus");
        assert_eq!(plugin_path("my-plugin"), "/org/opdbus/v1/plugins/my_plugin");
        assert_eq!(
